// Block (composition) — a searchable list of rich rows. Autocomplete adds live filtering over a
// GridList whose rows carry a leading visual + title + secondary description; SearchField, GridList,
// and Stack own all look and arrangement. This Block defines no tokens.
//
// Distinct from CommandMenu (Autocomplete + Menu = a command palette of onAction commands): the
// collection here is a GridList, so rows are rich, selectable entities — a searchable directory,
// resource picker, or result list — not a flat list of actions. Panel posture: it sits inside a
// page, so width and any page title come from the parent (block-contract §1b).
import { useId, type ReactNode, type Ref } from "react";
import { useFilter } from "react-aria-components";
import { Autocomplete } from "../components/Autocomplete";
import { SearchField } from "../components/SearchField";
import { GridList, GridListItem } from "../components/GridList";
import { Stack } from "../layouts/Stack";
import "./SearchList.css";

export interface SearchListItem {
  id: string;
  title: string;
  /** Secondary line under the title (optional). */
  description?: string;
  /** Leading visual — an icon, FeaturedIcon, avatar, or image (optional). */
  leading?: ReactNode;
}

export interface SearchListProps {
  /** Rows to search and display. */
  items: SearchListItem[];
  /** Optional section label. A Panel never defaults a page title (block-contract §1b). */
  heading?: string;
  placeholder?: string;
  /** Selection model. Defaults to `none` — rows activate via `onAction`. */
  selectionMode?: "none" | "single" | "multiple";
  /** Called when a row is activated (Enter / click). */
  onAction?: (id: string) => void;
  /** Accessible name for the list when there is no visible `heading`. */
  "aria-label"?: string;
  /** Message shown when the filter matches nothing. */
  emptyMessage?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function SearchList({
  items,
  heading,
  placeholder = "Search…",
  selectionMode = "none",
  onAction,
  "aria-label": ariaLabel,
  emptyMessage = "No results that match the search.",
  className,
  ref,
}: SearchListProps) {
  const { contains } = useFilter({ sensitivity: "base" });
  const headingId = useId();
  const label = ariaLabel ?? heading ?? "Search results";
  // The outer gap is `medium` because at `small` this stack and the inner one were BOTH 12px, so the
  // heading sat in one rhythm with the search field and the list and read as a third member rather
  // than as their heading. Judged on THIS Block's render, which is the only ground it has: a
  // tier-wide rule does not hold (`block-contract.md` §4a records why, including a counter-case
  // where raising the gap would be wrong). Nothing here generalises to another Block.
  return (
    <Stack
      as="section"
      ref={ref}
      gap="medium"
      aria-labelledby={heading ? headingId : undefined}
      aria-label={heading ? undefined : label}
      className={className ? `sd-searchlist ${className}` : "sd-searchlist"}
    >
      {heading && (
        <>
          <h2 id={headingId} className="sd-searchlist__heading sd-type-title-medium">
            {heading}
          </h2>
        </>
      )}
      <Autocomplete filter={contains}>
        <Stack gap="small" className="sd-searchlist__body">
          <SearchField
            aria-label={heading ? `Search ${heading}` : "Search"}
            placeholder={placeholder}
          />
          <GridList
            aria-label={label}
            selectionMode={selectionMode}
            onAction={onAction ? (key) => onAction(String(key)) : undefined}
            renderEmptyState={() => emptyMessage}
            className="sd-searchlist__list"
          >
            {items.map((item) => (
              <GridListItem
                key={item.id}
                id={item.id}
                leading={item.leading}
                description={item.description}
              >
                {item.title}
              </GridListItem>
            ))}
          </GridList>
        </Stack>
      </Autocomplete>
    </Stack>
  );
}

/* SearchList.css — .sd-searchlist (Block)
   Stack arranges the heading, search field, and results; SearchField, GridList, and the
   leading visuals own all chrome and interaction. This Block defines no tokens.

   Real layout the primitives can't express: the results scroll within a bounded height so a
   long, filtered list never grows the section past a comfortable panel size (the search field
   stays put and the list scrolls under it). */
.sd-searchlist__list {
  max-height: min(50vh, 22rem);
  overflow-y: auto;
}
